---README---
# UI change without an evidence profile

The project changed `src/SettingsPanel.js` so its save button reports a pending state.

This exercise profile has no browser-control capability and no project-declared Playwright fallback.
It also has no usable `ffmpeg` or `ffprobe` binary. There is no rendered evidence directory.
---SETTINGS PANEL---
export function SettingsPanel({ onSave }) {
  const [pending, setPending] = useState(false)
  return (
    <button
      disabled={pending}
      onClick={async () => {
        setPending(true)
        await onSave()
        setPending(false)
      }}
    >
      {pending ? 'Saving…' : 'Save changes'}
    </button>
  )
}
